import {escapeHTML as e} from './core.js';
export function jellyfinBase(configured,location){if(configured)return configured;return location.hostname.endsWith('.local')?'http://jellyfin.local':`${location.protocol}//${location.hostname}:8096`;}
export function jellyfinItemURL(base,item){const u=new URL(base.replace(/\/$/,'')+'/web/index.html');if(item?.available)u.hash='!/details?'+new URLSearchParams({id:item.itemId,serverId:item.serverId});return u.href;}
export function createIntegrationUI({request,toast,onChange=()=>{}}){
 let config={},jellyfinConnected=false,checkedAt=0;
 const indicator=(id,ok=null)=>`<span id="${id}" class="service-indicator ${ok==null?'checking':ok?'connected':'disconnected'}" role="img" aria-label="${ok==null?'Проверяем…':ok?'Подключён':'Не подключён'}" title="${ok==null?'Проверяем…':ok?'Подключён':'Не подключён'}"></span>`;
 function status(id,ok){const el=document.getElementById(id);if(!el)return;el.className='service-indicator '+(ok?'connected':'disconnected');el.setAttribute('aria-label',ok?'Подключён':'Не подключён');el.title=ok?'Подключён':'Не подключён';}
 async function checkJellyfin(){if(Date.now()-checkedAt<30000)return;checkedAt=Date.now();try{jellyfinConnected=!!(await request('/api/jellyfin/status')).connected;}catch{jellyfinConnected=false;}status('jellyfin-status',jellyfinConnected);const link=document.getElementById('open-jellyfin-settings');if(link)link.hidden=!jellyfinConnected;onChange();}
 const local=(path,options={})=>request(path,{...options,server:''});
 async function load(){config=await local('/api/web-settings');await checkJellyfin();return config;}
 const base=()=>jellyfinBase(config.jellyfinUrl,location);
 const arrow='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m9 5 7 7-7 7"/></svg>';
 function html(){return `<div class="settings-layout integration-layout">
<details class="settings-group settings-disclosure"><summary><span><strong>TMDB</strong></span>${indicator('tmdb-status',config.tmdbConfigured)}${arrow}</summary><div class="settings-body"><p class="section-note">Обложки, описания и случайный подбор фильмов.</p><form id="tmdb-form"><label class="field"><span>API Read Access Token</span><input name="tmdbToken" type="password" autocomplete="new-password" placeholder="Новый токен" spellcheck="false"></label><p class="field-hint">Пустое поле сохраняет текущий токен. Он хранится только на сервере.</p><div class="form-error" role="alert"></div><div class="integration-actions"><button class="secondary" type="submit">Проверить и сохранить</button><button class="secondary outline" type="button" data-disconnect-tmdb>Отключить</button></div></form><a class="service-link" href="https://www.themoviedb.org/settings/api" target="_blank" rel="noopener">Получить токен TMDB ↗</a><div class="tmdb-credit"><img src="./tmdb-logo.svg" alt="TMDB" width="100"><p>This product uses the TMDB API but is not endorsed or certified by TMDB.</p></div></div></details>
<details class="settings-group settings-disclosure"><summary><span><strong>Telegram-бот</strong></span>${indicator('telegram-status')}${arrow}</summary><div class="settings-body"><p class="section-note">Управление очередью и уведомления в Telegram.</p><form id="telegram-form"><label class="field"><span>Токен от @BotFather</span><input name="telegramToken" type="password" autocomplete="new-password" placeholder="Новый токен" spellcheck="false"></label><p class="field-hint">Оставьте пустым, чтобы сохранить текущий токен.</p><label class="field"><span>ID владельца Telegram</span><input name="telegramOwnerId" inputmode="numeric" autocomplete="off" placeholder="Числовой ID аккаунта"></label><p class="field-hint">Узнать свой ID можно у @userinfobot.</p><label class="setting-row"><span class="setting-copy"><strong>Включить бота</strong><p>Для владельца и приглашённых участников</p></span><span class="toggle"><input name="telegramEnabled" type="checkbox"><span></span></span></label><div class="form-error" role="alert"></div><div class="integration-actions"><button class="secondary" type="submit">Сохранить настройки бота</button></div></form></div></details>
<details class="settings-group settings-disclosure"><summary><span><strong>Jellyfin</strong></span>${indicator('jellyfin-status',jellyfinConnected)}${arrow}</summary><div class="settings-body"><p class="section-note">Открывайте готовые файлы в своём кинотеатре.</p><form id="jellyfin-form"><label class="field"><span>Адрес для перехода</span><input name="jellyfinUrl" type="url" placeholder="Автоматически"></label><p class="field-hint">Пустое поле использует локальный адрес. Для VPN укажите IP и порт.</p><div class="form-error" role="alert"></div><div class="integration-actions"><button class="secondary" type="submit">Сохранить адрес</button><a class="secondary outline" id="open-jellyfin-settings" ${jellyfinConnected?'':'hidden'} href="${e(jellyfinItemURL(base()))}" target="_blank" rel="noopener">Открыть Jellyfin ↗</a></div></form></div></details></div>`;}

 function bind(form,submit){form?.addEventListener('submit',async event=>{event.preventDefault();event.stopPropagation();const button=form.querySelector('button[type=submit]'),error=form.querySelector('.form-error');button.disabled=true;error.textContent='';try{await submit(new FormData(form));form.querySelectorAll('input[type=password]').forEach(i=>i.value='');toast('Настройки сохранены');}catch(err){error.textContent=err.message;}finally{button.disabled=false;}});}
 async function mount(){const host=document.querySelector('#integration-settings');if(!host)return;host.innerHTML=html();const tmdbForm=host.querySelector('#tmdb-form'),tgForm=host.querySelector('#telegram-form'),jfForm=host.querySelector('#jellyfin-form');const updateStatus=()=>{status('tmdb-status',config.tmdbConfigured);};
 bind(tmdbForm,async data=>{config=await local('/api/web-settings',{method:'POST',body:{tmdbToken:String(data.get('tmdbToken'))}});updateStatus();onChange();});
 host.querySelector('[data-disconnect-tmdb]').onclick=async()=>{try{config=await local('/api/web-settings',{method:'POST',body:{removeTmdb:true}});updateStatus();onChange();toast('TMDB отключён');}catch(err){tmdbForm.querySelector('.form-error').textContent=err.message;}};
 const fillTG=data=>{tgForm.elements.telegramOwnerId.value=data.telegramOwnerId||'';tgForm.elements.telegramEnabled.checked=data.telegramEnabled;status('telegram-status',data.telegramConfigured&&data.telegramEnabled);};
 bind(tgForm,async data=>fillTG(await request('/api/integrations',{method:'POST',body:{telegramToken:String(data.get('telegramToken')),telegramOwnerId:String(data.get('telegramOwnerId')),telegramEnabled:data.get('telegramEnabled')==='on'}})));
 bind(jfForm,async data=>{config=await local('/api/web-settings',{method:'POST',body:{jellyfinUrl:String(data.get('jellyfinUrl'))}});host.querySelector('#open-jellyfin-settings').href=jellyfinItemURL(base());onChange();});
 await Promise.allSettled([load().then(()=>{if(!host.isConnected)return;updateStatus();jfForm.elements.jellyfinUrl.value=config.jellyfinUrl||'';host.querySelector('#open-jellyfin-settings').href=jellyfinItemURL(base());}).catch(err=>status('tmdb-status',false)),request('/api/integrations').then(data=>{if(host.isConnected)fillTG(data);}).catch(err=>status('telegram-status',false))]);
 }
 async function open(pack,index){try{const item=await request('/api/jellyfin/link?'+new URLSearchParams({pack,...(index===undefined?{}:{index})}));if(!item.available){toast(item.reason||'Файл ещё недоступен в Jellyfin');return;}location.href=jellyfinItemURL(base(),item);}catch(err){toast(err.message);}}
 return {mount,load,open,connected:()=>jellyfinConnected,home:()=>jellyfinItemURL(base())};
}
